template <class T>
bool Plazza::SafeQueue<T>::tryPop(T &var)
{
    unsigned int size = 0;

    if (_mtx.trylock() && (size = _queue.size()) > 0) {
        var = _queue[size - 1];
        _queue.pop_back();
        _mtx.unlock();
        return (true);
    } else {
        if (size <= 0)
            _mtx.unlock();
        return (false);
    }
}

template <class T>
void Plazza::SafeQueue<T>::push(T var)
{
    _queue.push_front(var);
}

template <class T>
